{
  // firstname and lastname: name for the new account.
  // email: school email; this verified seeded address demonstrates duplicate-email 422.
  // password: must meet the registration password rules.
  // department: use an allowed department value.
  // A new registration requires an unused student.laverdad.edu.ph email and queues verification.
  "firstname": "Karl Ashton",
  "lastname": "Mahusay",
  "email": "karlborrow.test@student.laverdad.edu.ph",
  "password": "password123",
  "department": "BS Information Systems"
}

{
  // email: school account email; verified account returns 422.
  // An unverified account can return 200; a repeat within one minute returns 429.
  "email": "karlborrow.test@student.laverdad.edu.ph"
}

{
  // email: existing school account; unknown valid email returns 404.
  "email": "karlborrow.test@student.laverdad.edu.ph"
}

{
  // name: optional replacement display name.
  // status: equipment status enum.
  // Bad example: status "reserved" returns 422.
  "name": "Sony Alpha A7 IV (Studio Kit)",
  "status": "available"
}

{
  // approval_note: optional note for the pending booking.
  // Bad example: an invalid booking state returns 422.
  "approval_note": "Approved. Please bring student ID upon equipment pickup."
}

{
  // rejection_reason: required text; empty value returns 422.
  // Bad example: empty rejection_reason fails validation with 422.
  "rejection_reason": "Equipment is reserved for an official school event."
}

{
  // firstname: optional replacement name.
  // role: borrower, admin, or sysadmin; invalid role returns 422.
  // department: required when changing role to borrower.
  // Bad example: role "manager" returns 422.
  "firstname": "Karl Ashton",
  "role": "admin",
  "department": "BS Information Systems"
}

{
  // firstname and lastname: sender name.
  // email: valid sender email; malformed value returns 422.
  // message: required message text.
  // Bad example: an invalid email address returns 422.
  "firstname": "Karl Ashton",
  "lastname": "Mahusay",
  "email": "karlborrow.test@student.laverdad.edu.ph",
  "message": "Inquiring about equipment availability for an upcoming school project."
}
